class Solution {
    public List<Integer> partitionLabels(String s) {
        int[] remaining = new int[26];
        for (int i = 0; i < s.length(); i++) {
            remaining[s.charAt(i) - 'a']++;
        }

        boolean[] active = new boolean[26];
        int openCharacters = 0;
        int start = 0;
        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            if (!active[c]) {
                active[c] = true;
                openCharacters++;
            }
            remaining[c]--;
            if (remaining[c] == 0) {
                active[c] = false;
                openCharacters--;
            }
            if (openCharacters == 0) {
                result.add(i - start + 1);
                start = i + 1;
            }
        }
        return result;
    }
}

