class Solution {
    public List<Integer> partitionLabels(String s) {
        int[] first = new int[26];
        int[] last = new int[26];
        Arrays.fill(first, -1);
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) {
                first[c] = i;
            }
            last[c] = i;
        }

        List<Integer> result = new ArrayList<>();
        int start = 0;
        while (start < s.length()) {
            for (int end = start; end < s.length(); end++) {
                if (isClosedSegment(first, last, start, end)) {
                    result.add(end - start + 1);
                    start = end + 1;
                    break;
                }
            }
        }
        return result;
    }

    private boolean isClosedSegment(int[] first, int[] last, int start, int end) {
        for (int c = 0; c < 26; c++) {
            if (first[c] == -1) {
                continue;
            }
            boolean overlaps = first[c] <= end && last[c] >= start;
            if (overlaps && (first[c] < start || last[c] > end)) {
                return false;
            }
        }
        return true;
    }
}

import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

class Solution {
    public List<Integer> partitionLabels(String s) {
        int n = s.length();
        int[] first = new int[26];
        int[] last = new int[26];
        Arrays.fill(first, -1);

        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) {
                first[c] = i;
            }
            last[c] = i;
        }

        DSU dsu = new DSU(n);
        for (int c = 0; c < 26; c++) {
            if (first[c] == -1) {
                continue;
            }
            for (int i = first[c] + 1; i <= last[c]; i++) {
                dsu.union(first[c], i);
            }
        }

        List<Integer> result = new ArrayList<>();
        int start = 0;
        int root = dsu.find(0);
        for (int i = 1; i < n; i++) {
            int current = dsu.find(i);
            if (current != root) {
                result.add(i - start);
                start = i;
                root = current;
            }
        }
        result.add(n - start);
        return result;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        }
    }
}
